    results.append(simple_calculator(10, '+', 5))
    results.append(simple_calculator(10, '-', 3))
    results.append(simple_calculator(7, '*', 8))
    results.append(simple_calculator(100, '/', 10))
    results.append(simple_calculator(15, '/', 0))
    results.append(simple_calculator(2.5, '+', 3.5))
    results.append(simple_calculator(100, '%', 5))
    results.append(simple_calculator(-5, '*', 4))
    results.append(simple_calculator(0, '/', 5))
