import collections, functools, itertools, math, operator, re, sys, typing

def run_length_decode(encoded_string: str) -> str:
    """Decodes a run-length encoded string."""
    decoded_parts: list[str] = []
    i: int = 0
    n: int = len(encoded_string)

    while i < n:
        count_str: str = ''
        while i < n and encoded_string[i].isdigit():
            count_str += encoded_string[i]
            i += 1

        if not count_str:
            raise ValueError("Invalid encoding: count expected, but not found.")

        count: int = int(count_str)

        if i < n:
            char: str = encoded_string[i]
            decoded_parts.append(char * count)
            i += 1
        else:
            raise ValueError("Invalid encoding: character expected, but not found.")

    return ''.join(decoded_parts)

