def is_brackets_balanced(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    opening_brackets = {'(', '[', '{'}

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False, "mismatched or unopened bracket", char
        else:
            return False, "invalid character detected", char

    return not stack, "all brackets balanced", "no issues"

