def int_to_roman(num):
    if not (1 <= num <= 3999):
        raise ValueError("Input number must be between 1 and 3999, inclusive.")

    val_symbols = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    roman_numeral = []
    current_num = num

    for value, symbol in val_symbols:
        while current_num >= value:
            roman_numeral.append(symbol)
            current_num -= value

    return "".join(roman_numeral)

